CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,email text UNIQUE NOT NULL,name text NOT NULL,role text NOT NULL CHECK(role IN ('owner','participant')),age integer,country text,password_hash text NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id text REFERENCES users(id),csrf text NOT NULL,expires_at double precision NOT NULL);
CREATE TABLE IF NOT EXISTS studies(id text PRIMARY KEY,owner_id text REFERENCES users(id),title text NOT NULL DEFAULT '',question text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','moderating','open','closed')),version integer NOT NULL DEFAULT 1,quota integer,age_min integer,age_max integer,country text NOT NULL DEFAULT '',created_at double precision NOT NULL,published_at double precision,deadline double precision,closed_at double precision,moderation_reason text NOT NULL DEFAULT '',moderation_provider text,closure_reason text);
CREATE TABLE IF NOT EXISTS options(id text PRIMARY KEY,study_id text REFERENCES studies(id) ON DELETE CASCADE,position integer NOT NULL,text text NOT NULL DEFAULT '',image text,UNIQUE(study_id,position));
CREATE TABLE IF NOT EXISTS answers(id text PRIMARY KEY,study_id text REFERENCES studies(id),user_id text REFERENCES users(id),personal_id text REFERENCES options(id),prediction_id text REFERENCES options(id),accepted_at double precision NOT NULL,UNIQUE(study_id,user_id));
CREATE INDEX IF NOT EXISTS answers_study ON answers(study_id);
CREATE TABLE IF NOT EXISTS ledger(id text PRIMARY KEY,user_id text REFERENCES users(id),study_id text REFERENCES studies(id),kind text NOT NULL CHECK(kind IN ('base','bonus','spin','redeem')),amount integer NOT NULL CHECK(amount<>0),operation_id text,created_at double precision NOT NULL,UNIQUE(user_id,study_id,kind),UNIQUE(user_id,operation_id));
CREATE TABLE IF NOT EXISTS events(event_id text PRIMARY KEY,type text NOT NULL,study_id text REFERENCES studies(id),participant_id text,at double precision NOT NULL,fact_version integer);
CREATE UNIQUE INDEX IF NOT EXISTS first_open ON events(study_id,participant_id) WHERE type='opened';
CREATE INDEX IF NOT EXISTS events_study_type ON events(study_id,type);
CREATE TABLE IF NOT EXISTS facts(study_id text REFERENCES studies(id),version integer NOT NULL,metric text NOT NULL,unit text NOT NULL,start_date text NOT NULL,end_date text NOT NULL,is_rate boolean NOT NULL,values_json jsonb NOT NULL,created_at double precision NOT NULL,PRIMARY KEY(study_id,version));
CREATE TABLE IF NOT EXISTS moderation_jobs(id text PRIMARY KEY,study_id text REFERENCES studies(id),version integer NOT NULL,state text NOT NULL DEFAULT 'pending',enqueued_at double precision NOT NULL DEFAULT 0,lease_until double precision NOT NULL DEFAULT 0,attempt integer NOT NULL DEFAULT 0,created_at double precision NOT NULL,UNIQUE(study_id,version));
CREATE TABLE IF NOT EXISTS notifications(id text PRIMARY KEY,user_id text REFERENCES users(id),kind text NOT NULL,reference text NOT NULL,study_id text REFERENCES studies(id),title text NOT NULL,body text NOT NULL,created_at double precision NOT NULL,read_at double precision,UNIQUE(user_id,kind,reference));
CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,created_at);
CREATE TABLE IF NOT EXISTS devices(id text PRIMARY KEY,user_id text REFERENCES users(id),name text NOT NULL,token_hash text UNIQUE NOT NULL,created_at double precision NOT NULL,expires_at double precision NOT NULL,last_seen double precision,revoked_at double precision);
CREATE TABLE IF NOT EXISTS notification_deliveries(notification_id text REFERENCES notifications(id),device_id text REFERENCES devices(id),delivered_at double precision NOT NULL,PRIMARY KEY(notification_id,device_id));
CREATE TABLE IF NOT EXISTS rewards(id text PRIMARY KEY,owner_id text REFERENCES users(id),title text NOT NULL,description text NOT NULL,cost integer NOT NULL,channel text NOT NULL CHECK(channel IN ('guaranteed','wheel')),is_demo boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,created_at double precision NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_wheel_prize ON rewards(channel) WHERE channel='wheel' AND active;
CREATE TABLE IF NOT EXISTS inventory(id text PRIMARY KEY,reward_id text REFERENCES rewards(id),code text UNIQUE NOT NULL,claim_id text UNIQUE);
CREATE TABLE IF NOT EXISTS reward_operations(id text PRIMARY KEY,user_id text REFERENCES users(id),request_key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at double precision NOT NULL,UNIQUE(user_id,request_key));
CREATE TABLE IF NOT EXISTS claims(id text PRIMARY KEY,user_id text REFERENCES users(id),reward_id text REFERENCES rewards(id),inventory_id text UNIQUE REFERENCES inventory(id),operation_id text UNIQUE REFERENCES reward_operations(id) DEFERRABLE INITIALLY DEFERRED,created_at double precision NOT NULL);
